import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a row-per-block GEMV:
#   C[row] = sum_k A[row, k] * B[k]
#
# One CUDA block handles one row of A. Threads within the block stride over
# K using vectorized 128-bit (float4) global loads for both A and B to
# maximize memory bandwidth utilization (this kernel is heavily memory-
# bandwidth bound since A is huge: M x K x 4 bytes). A scalar tail loop
# handles any remaining elements when K is not a multiple of 4. After the
# per-thread partial dot product is accumulated, a warp-level shuffle
# reduction followed by a block-level reduction (through shared memory)
# produces the final scalar for that row.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry gemv_kernel(
    .param .u64 gemv_kernel_param_0,
    .param .u64 gemv_kernel_param_1,
    .param .u64 gemv_kernel_param_2,
    .param .u32 gemv_kernel_param_3,
    .param .u32 gemv_kernel_param_4
)
{
    .reg .pred %p<32>;
    .reg .f32  %f<50>;
    .reg .b32  %r<80>;
    .reg .b64  %rd<60>;
    // Two shared arrays hold per-warp partial sums for the two rows
    // processed cooperatively by this CTA (row-pair tiling).
    .shared .align 4 .b8 warp_sums0[128];
    .shared .align 4 .b8 warp_sums1[128];
    ld.param.u64 %rd1, [gemv_kernel_param_0];   // A ptr
    ld.param.u64 %rd2, [gemv_kernel_param_1];   // B ptr
    ld.param.u64 %rd3, [gemv_kernel_param_2];   // C ptr
    ld.param.u32 %r1,  [gemv_kernel_param_3];   // M
    ld.param.u32 %r2,  [gemv_kernel_param_4];   // K
    cvta.to.global.u64 %rd4, %rd1;
    cvta.to.global.u64 %rd5, %rd2;
    cvta.to.global.u64 %rd6, %rd3;
    mov.u32 %r3, %ctaid.x;                 // block id
    shl.b32 %r30, %r3, 1;                  // row0 = blockIdx.x * 2
    setp.ge.s32 %p1, %r30, %r1;
    @%p1 bra DONE;
    add.s32 %r31, %r30, 1;                 // row1 = row0 + 1
    setp.ge.s32 %p10, %r31, %r1;           // p10 = row1 invalid
    @%p10 bra SINGLE;
    mov.u32 %r4, %tid.x;                   // tid
    mov.u32 %r5, %ntid.x;                  // threads per block
    // A0 (row0) base pointer
    mul.wide.u32 %rd7, %r30, %r2;
    shl.b64 %rd8, %rd7, 2;
    add.s64 %rd9, %rd4, %rd8;
    // A1 (row1) base pointer
    mul.wide.u32 %rd11, %r31, %r2;
    shl.b64 %rd12, %rd11, 2;
    add.s64 %rd13, %rd4, %rd12;
    mov.f32 %f1, 0f00000000;               // sum0
    mov.f32 %f2, 0f00000000;               // sum1
    shr.u32 %r7, %r2, 2;                   // vec_K = K / 4
    mov.u32 %r6, %r4;                      // vi = tid
VLOOP2:
    setp.ge.s32 %p2, %r6, %r7;
    @%p2 bra VLOOP2_END;
    mul.wide.u32 %rd20, %r6, 16;           // byte offset = vi * 16
    add.s64 %rd21, %rd9, %rd20;            // &A0[row0, vi*4]
    add.s64 %rd22, %rd13, %rd20;           // &A1[row1, vi*4]
    add.s64 %rd23, %rd5, %rd20;            // &B[vi*4]  (shared across rows)
    ld.global.v4.f32 {%f10, %f11, %f12, %f13}, [%rd21];
    ld.global.v4.f32 {%f14, %f15, %f16, %f17}, [%rd22];
    ld.global.v4.f32 {%f18, %f19, %f20, %f21}, [%rd23];
    fma.rn.f32 %f1, %f10, %f18, %f1;
    fma.rn.f32 %f1, %f11, %f19, %f1;
    fma.rn.f32 %f1, %f12, %f20, %f1;
    fma.rn.f32 %f1, %f13, %f21, %f1;
    fma.rn.f32 %f2, %f14, %f18, %f2;
    fma.rn.f32 %f2, %f15, %f19, %f2;
    fma.rn.f32 %f2, %f16, %f20, %f2;
    fma.rn.f32 %f2, %f17, %f21, %f2;
    add.s32 %r6, %r6, %r5;
    bra VLOOP2;
VLOOP2_END:
    mul.lo.s32 %r8, %r7, 4;                // rem_start = vec_K * 4
    add.s32 %r9, %r8, %r4;                 // i = rem_start + tid
TLOOP2:
    setp.ge.s32 %p8, %r9, %r2;
    @%p8 bra TLOOP2_END;
    mul.wide.u32 %rd25, %r9, 4;
    add.s64 %rd26, %rd9, %rd25;
    add.s64 %rd27, %rd13, %rd25;
    add.s64 %rd28, %rd5, %rd25;
    ld.global.f32 %f22, [%rd26];
    ld.global.f32 %f23, [%rd27];
    ld.global.f32 %f24, [%rd28];
    fma.rn.f32 %f1, %f22, %f24, %f1;
    fma.rn.f32 %f2, %f23, %f24, %f2;
    add.s32 %r9, %r9, %r5;
    bra TLOOP2;
TLOOP2_END:
    // ---- warp-level reduction for sum0 ----
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 16, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 8, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 4, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 2, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 1, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    // ---- warp-level reduction for sum1 ----
    mov.b32 %r12, %f2;
    shfl.sync.down.b32 %r13|%p4, %r12, 16, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f2, %f2, %f5;
    mov.b32 %r12, %f2;
    shfl.sync.down.b32 %r13|%p4, %r12, 8, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f2, %f2, %f5;
    mov.b32 %r12, %f2;
    shfl.sync.down.b32 %r13|%p4, %r12, 4, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f2, %f2, %f5;
    mov.b32 %r12, %f2;
    shfl.sync.down.b32 %r13|%p4, %r12, 2, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f2, %f2, %f5;
    mov.b32 %r12, %f2;
    shfl.sync.down.b32 %r13|%p4, %r12, 1, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f2, %f2, %f5;
    and.b32 %r20, %r4, 31;                 // lane id
    shr.u32 %r21, %r4, 5;                  // warp id
    setp.ne.s32 %p5, %r20, 0;
    @%p5 bra SKIP_STORE2;
    mov.u32 %r22, warp_sums0;
    shl.b32 %r23, %r21, 2;
    add.s32 %r24, %r22, %r23;
    st.shared.f32 [%r24], %f1;
    mov.u32 %r25, warp_sums1;
    add.s32 %r26, %r25, %r23;
    st.shared.f32 [%r26], %f2;
SKIP_STORE2:
    bar.sync 0;
    setp.ne.s32 %p6, %r21, 0;
    @%p6 bra DONE;
    shr.u32 %r27, %r5, 5;                  // num warps
    mov.f32 %f6, 0f00000000;
    mov.f32 %f7, 0f00000000;
    setp.ge.u32 %p7, %r20, %r27;
    @%p7 bra SKIP_LOAD2;
    mov.u32 %r28, warp_sums0;
    shl.b32 %r29, %r20, 2;
    add.s32 %r32, %r28, %r29;
    ld.shared.f32 %f6, [%r32];
    mov.u32 %r33, warp_sums1;
    add.s32 %r34, %r33, %r29;
    ld.shared.f32 %f7, [%r34];
SKIP_LOAD2:
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 16, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 8, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 4, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 2, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 1, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r12, %f7;
    shfl.sync.down.b32 %r13|%p4, %r12, 16, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f7, %f7, %f5;
    mov.b32 %r12, %f7;
    shfl.sync.down.b32 %r13|%p4, %r12, 8, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f7, %f7, %f5;
    mov.b32 %r12, %f7;
    shfl.sync.down.b32 %r13|%p4, %r12, 4, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f7, %f7, %f5;
    mov.b32 %r12, %f7;
    shfl.sync.down.b32 %r13|%p4, %r12, 2, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f7, %f7, %f5;
    mov.b32 %r12, %f7;
    shfl.sync.down.b32 %r13|%p4, %r12, 1, 31, -1;
    mov.b32 %f5, %r13;
    add.f32 %f7, %f7, %f5;
    setp.ne.s32 %p9, %r20, 0;
    @%p9 bra DONE;
    mul.wide.u32 %rd30, %r30, 4;
    add.s64 %rd31, %rd6, %rd30;
    st.global.f32 [%rd31], %f6;
    mul.wide.u32 %rd32, %r31, 4;
    add.s64 %rd33, %rd6, %rd32;
    st.global.f32 [%rd33], %f7;
    bra DONE;
SINGLE:
    // Fallback: only row0 is valid (tail case when M is odd).
    mov.u32 %r4, %tid.x;
    mov.u32 %r5, %ntid.x;
    mul.wide.u32 %rd7, %r30, %r2;
    shl.b64 %rd8, %rd7, 2;
    add.s64 %rd9, %rd4, %rd8;
    mov.f32 %f1, 0f00000000;
    shr.u32 %r7, %r2, 2;
    mov.u32 %r6, %r4;
VLOOP1:
    setp.ge.s32 %p2, %r6, %r7;
    @%p2 bra VLOOP1_END;
    mul.wide.u32 %rd10, %r6, 16;
    add.s64 %rd11, %rd9, %rd10;
    add.s64 %rd12, %rd5, %rd10;
    ld.global.v4.f32 {%f10, %f11, %f12, %f13}, [%rd11];
    ld.global.v4.f32 {%f14, %f15, %f16, %f17}, [%rd12];
    fma.rn.f32 %f1, %f10, %f14, %f1;
    fma.rn.f32 %f1, %f11, %f15, %f1;
    fma.rn.f32 %f1, %f12, %f16, %f1;
    fma.rn.f32 %f1, %f13, %f17, %f1;
    add.s32 %r6, %r6, %r5;
    bra VLOOP1;
VLOOP1_END:
    mul.lo.s32 %r8, %r7, 4;
    add.s32 %r9, %r8, %r4;
TLOOP1:
    setp.ge.s32 %p8, %r9, %r2;
    @%p8 bra TLOOP1_END;
    mul.wide.u32 %rd15, %r9, 4;
    add.s64 %rd16, %rd9, %rd15;
    add.s64 %rd17, %rd5, %rd15;
    ld.global.f32 %f18, [%rd16];
    ld.global.f32 %f19, [%rd17];
    fma.rn.f32 %f1, %f18, %f19, %f1;
    add.s32 %r9, %r9, %r5;
    bra TLOOP1;
TLOOP1_END:
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 16, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 8, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 4, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 2, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    mov.b32 %r10, %f1;
    shfl.sync.down.b32 %r11|%p3, %r10, 1, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f1, %f1, %f4;
    and.b32 %r20, %r4, 31;
    shr.u32 %r21, %r4, 5;
    setp.ne.s32 %p4, %r20, 0;
    @%p4 bra SKIP_STORE1;
    mov.u32 %r22, warp_sums0;
    shl.b32 %r23, %r21, 2;
    add.s32 %r24, %r22, %r23;
    st.shared.f32 [%r24], %f1;
SKIP_STORE1:
    bar.sync 0;
    setp.ne.s32 %p6, %r21, 0;
    @%p6 bra DONE;
    shr.u32 %r27, %r5, 5;
    mov.f32 %f6, 0f00000000;
    setp.ge.u32 %p7, %r20, %r27;
    @%p7 bra SKIP_LOAD1;
    mov.u32 %r28, warp_sums0;
    shl.b32 %r29, %r20, 2;
    add.s32 %r32, %r28, %r29;
    ld.shared.f32 %f6, [%r32];
SKIP_LOAD1:
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 16, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 8, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 4, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 2, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    mov.b32 %r10, %f6;
    shfl.sync.down.b32 %r11|%p3, %r10, 1, 31, -1;
    mov.b32 %f4, %r11;
    add.f32 %f6, %f6, %f4;
    setp.ne.s32 %p9, %r20, 0;
    @%p9 bra DONE;
    mul.wide.u32 %rd30, %r30, 4;
    add.s64 %rd31, %rd6, %rd30;
    st.global.f32 [%rd31], %f6;
DONE:
    ret;
}
"""

_ENTRY_NAME = "gemv_kernel"
_THREADS = 256

_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """Sanity check that the PTX module exposes the expected entry point."""
    module = _get_module()
    entry = module.function(_ENTRY_NAME)
    return entry is not None


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication C = A @ B implemented as a hand-written
    PTX kernel executed through cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self):
        super(ModelNew, self).__init__()
        self._module = None

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "A and B must be CUDA tensors"
        assert A.dim() == 2, "A must be 2D (M, K)"
        assert B.dim() == 2 and B.size(1) == 1, "B must be (K, 1)"
        assert A.dtype == torch.float32 and B.dtype == torch.float32

        if self._module is None:
            self._module = _get_module()

        M, K = A.shape
        assert B.size(0) == K

        A_c = A.contiguous()
        B_c = B.contiguous()
        C = torch.empty((M, 1), device=A.device, dtype=torch.float32)

        stream = torch.cuda.current_stream()

        grid = ((int(M) + 1) // 2, 1, 1)
        block = (_THREADS, 1, 1)

        self._module.launch(
            _ENTRY_NAME,
            grid,
            block,
            [
                u64(A_c.data_ptr()),
                u64(B_c.data_ptr()),
                u64(C.data_ptr()),
                i32(int(M)),
                i32(int(K)),
            ],
            stream=stream,
        )

        return C

