#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// One block per row of A. Each thread strides over K (vectorized as float4),
// accumulates a partial dot-product with B, then a block-wide reduction
// produces the final scalar for that row.
template <int THREADS>
__global__ void gemv_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
  int row = blockIdx.x;
  if (row >= M) return;

  const float* Arow = A + (int64_t)row * (int64_t)K;

  int tid = threadIdx.x;

  int K4 = K / 4;          // number of float4 groups
  int rem = K - K4 * 4;    // leftover scalar elements

  // Vectorized views via CUTE tensors
  auto gA4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(Arow)),
                          make_shape(K4));
  auto gB4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(B)),
                          make_shape(K4));

  float sum = 0.0f;

  for (int i = tid; i < K4; i += THREADS) {
    float4 a = gA4(i);
    float4 b = gB4(i);
    sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
  }

  // Handle tail elements (K not divisible by 4)
  int tail_start = K4 * 4;
  if (rem > 0) {
    auto gA1 = make_tensor(make_gmem_ptr(Arow + tail_start), make_shape(rem));
    auto gB1 = make_tensor(make_gmem_ptr(B + tail_start), make_shape(rem));
    for (int i = tid; i < rem; i += THREADS) {
      sum += gA1(i) * gB1(i);
