  if (warp_id == 0) {
    float v = (lane < NUM_WARPS) ? warp_sums[lane] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      v += __shfl_down_sync(0xFFFFFFFF, v, offset);
    }
    if (lane == 0) {
